function validate([n, queries]) {
  if (!Number.isInteger(n) || n < 3 || n > 100000) return 'n is between 3 and 100000.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 100000 roads.';
  const seen = new Set();
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is a pair [u, v].';
    const [u, v] = query;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || u >= v || v >= n) return 'Each query needs 0 <= u < v < n.';
    if (v - u < 2) return 'Each new road must skip at least one city (v - u >= 2).';
    if (seen.has(u * n + v)) return 'The same road cannot be built twice.';
    seen.add(u * n + v);
  }
  // Sort by start (longer roads first on ties); a stack of enclosing road ends exposes any crossing pair.
  const sorted = [...queries].sort((a, b) => a[0] - b[0] || b[1] - a[1]);
  const ends = [];
  for (const [u, v] of sorted) {
    while (ends.length > 0 && ends[ends.length - 1] <= u) ends.pop();
    if (ends.length > 0 && ends[ends.length - 1] < v) return 'Two roads cross; no road may start inside another and end outside it.';
    ends.push(v);
  }
  return null;
}

