function shortestDistanceAfterQueries(n, queries) {
  const next = Array.from({ length: n }, (_, city) => city + 1);
  const onPath = new Array(n).fill(true);
  let remaining = n;
  const answer = [];
  for (const [u, v] of queries) {
    if (onPath[u] && next[u] < v) {
      let city = next[u];
      while (city < v) {
        onPath[city] = false;
        remaining--;
        city = next[city];
      }
      next[u] = v;
    }
    answer.push(remaining - 1);
  }
  return answer;
}

