function shortestDistanceAfterQueries(n, queries) {
  // Every road leads to a larger city, so one left-to-right pass settles all distances.
  const roads = Array.from({ length: n }, (_, city) => (city + 1 < n ? [city + 1] : []));
  const answer = [];
  for (const [u, v] of queries) {
    roads[u].push(v);
    const dist = new Array(n).fill(Infinity);
    dist[0] = 0;
    for (let city = 0; city < n; city++) {
      for (const to of roads[city]) dist[to] = Math.min(dist[to], dist[city] + 1);
    }
    answer.push(dist[n - 1]);
  }
  return answer;
}

