function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 + Math.floor(rand() * 98001) : 3 + Math.floor(rand() * 10);
  const cap = large ? 2000 : 1 + Math.floor(rand() * 8);
  const openRate = large ? Math.min(0.9, (cap / n) * (0.5 + rand())) : 0.3 + rand() * 0.6;
  const closeRate = large ? Math.pow(10, -2.5 + 2.2 * rand()) : 0.2 + rand() * 0.6;
  // Sweep the cities with a stack of open roads; closing them in stack order means no two roads cross.
  const roads = [];
  const open = [];
  for (let city = 0; city < n; city++) {
    let lastStart = -1;
    while (open.length > 0 && open[open.length - 1] <= city - 2 && (city === n - 1 || rand() < closeRate)) {
      const start = open.pop();
      if (start !== lastStart) roads.push([start, city]);
      lastStart = start;
    }
    while (city <= n - 3 && open.length < 3 * cap && rand() < openRate) open.push(city);
  }
  // Shuffle so that outer and inner roads arrive in any order, then keep at most cap of them.
  for (let i = roads.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [roads[i], roads[j]] = [roads[j], roads[i]];
  }
  if (roads.length === 0) {
    const u = Math.floor(rand() * (n - 2));
    roads.push([u, u + 2 + Math.floor(rand() * (n - u - 2))]);
  }
  return [n, roads.slice(0, cap)];
}
